                  </SortableHead>
                  <SortableHead
                    sortKey="duration"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-28"
                  >
                    Duration
                  </SortableHead>
                  <SortableHead
                    sortKey="cost"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-28"
                  >
                    Cost
                  </SortableHead>
                  <SortableHead
                    sortKey="when"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-32"
                  >
                    When
                  </SortableHead>
