        <div className="flex flex-wrap items-center gap-1.5 pl-9">
          {turn.toolCalls.map((tc) => (
            <Chip
              key={tc.name}
              onClick={() => openDetail({ type: "trace", id: turn.traceId })}
              title={`View ${tc.name} in the trace`}
