} from "../mock-data";
import { Piece, PieceRow, useEntering } from "../piece";

// While the entrance runs, the table and its scroll container keep 3D and
// do not clip so each row's lift reads, and the row lines move onto the
// cells: under collapsed borders the table paints them, so they would show
// before their row has landed. A transparent cell border keeps the row
// heights the same as at rest; the visible line is an inset shadow.
const ENTRANCE_TABLE =
	"transform-3d [&_[data-slot=table-container]]:overflow-visible [&_[data-slot=table-container]]:transform-3d [&_table]:transform-3d [&_thead]:transform-3d [&_tbody]:transform-3d " +
	"[&_table]:border-separate [&_table]:border-spacing-0 [&_th]:border-b [&_td]:border-b [&_th]:border-transparent [&_td]:border-transparent " +
	"[&_th]:shadow-[inset_0_-1px_0_0] [&_td]:shadow-[inset_0_-1px_0_0] [&_th]:shadow-border/50 [&_td]:shadow-border/50 dark:[&_th]:shadow-border/40 dark:[&_td]:shadow-border/40 [&_tbody_tr:last-child_td]:shadow-none";

// Quintiles drive the heat shade on the Duration and Cost cells.
const COST_QUANTILES = quintiles(TRACE_ROWS.map((t) => t.costValue));
const DURATION_QUANTILES = quintiles(TRACE_ROWS.map((t) => t.durationMs));

const MODELS = [...new Set(TRACE_ROWS.map((t) => t.model))];
const WORKFLOW_NAMES = [
	...new Set(TRACE_ROWS.flatMap((t) => (t.workflowName ? [t.workflowName] : []))),
];
const CUSTOMERS = [
	...new Set(TRACE_ROWS.flatMap((t) => (t.customer ? [t.customer] : []))),
];

// Colored icons for the dropdown *options* only — the closed trigger keeps the
// neutral outline icon, matching the real traces toolbar.
const WorkflowIconFilled = (p: { className?: string }) => (
	<IconSitemapFilled className={cn(p.className, "text-emerald-500")} />
);
const MetaValueIcon = (p: { className?: string }) => (
	<IconTagFilled className={cn(p.className, "text-fuchsia-500")} />
);

// The metadata filter's mock key/value catalog + a deterministic value per row.
const META_KEYS = ["environment", "plan", "region"] as const;
const META_VALUES: Record<(typeof META_KEYS)[number], string[]> = {
	environment: ["production", "staging"],
	plan: ["enterprise", "pro", "free"],
	region: ["us-east-1", "eu-west-1"],
};
const metaValueFor = (key: (typeof META_KEYS)[number], i: number) =>
	META_VALUES[key][i % META_VALUES[key].length]!;

// Prompt version option identity — lime, like the agent page's versions card.
const PromptVersionIcon = (p: { className?: string }) => (
	<IconFileHorizontalFilled
		className={cn(p.className, "text-lime-400 dark:text-lime-600")}
	/>
);

type SecondaryFilter = "workflow" | "customer" | "meta" | "prompt";

/** The "+ Filter" menu that summons the collapsed secondary filters — the real
 * page's AddFilterMenu, minus the URL plumbing. */
function AddFilterMenu({
	showWorkflow,
	showCustomer,
	showMeta,
	showPrompt,
	onAdd,
}: {
	showWorkflow: boolean;
	showCustomer: boolean;
	showMeta: boolean;
	showPrompt: boolean;
	onAdd: (k: SecondaryFilter) => void;
}) {
	const group = useFilterGroupItem();
	// Insert the summoned select only once the close animation completes, so the
	// "+ Filter" anchor doesn't shift mid-exit (same trick as the real page).
	const pendingAdd = useRef<SecondaryFilter | null>(null);
	return (
		<DropdownMenu
			modal={false}
			open={group.open}
			onOpenChange={group.onOpenChange}
			onOpenChangeComplete={(open) => {
				if (!open && pendingAdd.current) {
					onAdd(pendingAdd.current);
					pendingAdd.current = null;
				}
			}}
		>
			<DropdownMenuTrigger
				render={
					<Button
						variant="outline"
						size="icon"
						className="font-normal transition-[color,box-shadow] bg-card active:scale-100 text-muted-foreground/50 hover:text-muted-foreground/50 aria-expanded:text-muted-foreground/50"
						onMouseEnter={group.onTriggerMouseEnter}
					/>
				}
			>
				{/* Raw hex like the FilterSelect trigger icons — opacity on icons
				    reads muddier than on text. */}
				<IconFilter2 className="text-[#B8B8B8] dark:text-[#5B5B5B]" />
			</DropdownMenuTrigger>
			<DropdownMenuContent className="w-auto min-w-36" align="start" sideOffset={8}>
				{!showWorkflow && (
					<DropdownMenuItem
						onClick={() => {
							pendingAdd.current = "workflow";
						}}
					>
						<IconSitemap />
						Workflow
					</DropdownMenuItem>
				)}
				{!showCustomer && (
					<DropdownMenuItem
						onClick={() => {
							pendingAdd.current = "customer";
						}}
					>
						<IconUser />
						Customer
					</DropdownMenuItem>
				)}
				{!showMeta && (
					<DropdownMenuItem
						onClick={() => {
							pendingAdd.current = "meta";
						}}
					>
						<IconTag />
						Metadata
					</DropdownMenuItem>
				)}
				{!showPrompt && (
					<DropdownMenuItem
						onClick={() => {
							pendingAdd.current = "prompt";
						}}
					>
						<IconFileHorizontal />
						Prompt version
					</DropdownMenuItem>
				)}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

type TraceSortKey = "when" | "cost" | "duration" | "tokens" | "spans";

export function TracesTab() {
	const { openDetail } = useDemo();

	const [agentFilter, setAgentFilter] = useState("");
	const [modelFilter, setModelFilter] = useState("");
	const [workflowFilter, setWorkflowFilter] = useState("");
	const [customerFilter, setCustomerFilter] = useState("");
	const [metaKeyFilter, setMetaKeyFilter] = useState("");
	const [metaValueFilter, setMetaValueFilter] = useState("");
	// Prompt version (an id from PROMPT_VERSIONS) — versions belong to one
	// agent, so this filter and the agent filter are kept in agreement.
	const [promptFilter, setPromptFilter] = useState("");
	const [errorsOnly, setErrorsOnly] = useState(false);
	const [pageSize, setPageSize] = useState(25);
	const { sort, toggle } = useTableSort<TraceSortKey>();

	// Secondary filters stay out of the toolbar until summoned via "+ Filter".
	const [added, setAdded] = useState<Set<SecondaryFilter>>(() => new Set());
	const addFilter = (k: SecondaryFilter) =>
		setAdded((s) => new Set(s).add(k));
	const removeFilter = (k: SecondaryFilter) =>
		setAdded((s) => {
			const next = new Set(s);
			next.delete(k);
			return next;
		});
	const showWorkflow = added.has("workflow") || !!workflowFilter;
	const showCustomer = added.has("customer") || !!customerFilter;
	const showMeta = added.has("meta") || !!metaKeyFilter;
	const showPrompt = added.has("prompt") || !!promptFilter;
	const canAddFilter =
		!showWorkflow || !showCustomer || !showMeta || !showPrompt;
	const hasFilters = !!(
		agentFilter ||
		modelFilter ||
		workflowFilter ||
		customerFilter ||
		metaKeyFilter ||
		promptFilter ||
		errorsOnly
	);

	const metaKey = META_KEYS.includes(metaKeyFilter as (typeof META_KEYS)[number])
		? (metaKeyFilter as (typeof META_KEYS)[number])
		: null;

	const filtered = TRACE_ROWS.filter(
		(t) =>
			(!agentFilter || t.agentName === agentFilter) &&
			(!modelFilter || t.model === modelFilter) &&
			(!workflowFilter || t.workflowName === workflowFilter) &&
			(!customerFilter || t.customer === customerFilter) &&
			(!promptFilter ||
				promptVersionOf(t.agentName, t.traceId)?.id === promptFilter) &&
			(!metaKey ||
				!metaValueFilter ||
				metaValueFor(metaKey, TRACE_ROWS.indexOf(t)) === metaValueFilter) &&
			(!errorsOnly || (t.errors ?? 0) > 0),
	);
	const rows = sortRows<TraceRow, TraceSortKey>(filtered, sort, {
		when: (t) => -TRACE_ROWS.indexOf(t),
		cost: (t) => t.costValue,
		duration: (t) => t.durationMs,
		tokens: (t) => t.tokens,
		spans: (t) => t.spans,
	});

	const agentOptions = AGENTS.map((a) => ({
		value: a.name,
		label: a.name,
		icon: (p: { className?: string }) => (
			<AgentIcon name={a.name} className={p.className} />
		),
	}));
	// Prompt versions for the filter: the picked agent's, or every agent's
	// (labelled with the agent) when none is picked. Newest first.
	const promptOptions = PROMPT_VERSIONS.filter(
		(v) => !agentFilter || v.agentName === agentFilter,
	)
		.slice()
		.reverse()
		.map((v) => ({
			value: v.id,
			label: `${agentFilter ? "" : `${v.agentName} · `}v${v.number}`,
			hint: v.current ? "current" : undefined,
			icon: PromptVersionIcon,
		}));
	const promptAgentOf = (versionId: string) =>
		PROMPT_VERSIONS.find((v) => v.id === versionId)?.agentName ?? "";
	const modelOptions = MODELS.map((m) => ({
		value: m,
		label: formatModelName(m),
		icon: (p: { className?: string }) => (
			<ModelLogo modelId={m} className={p.className} />
		),
	}));
	const workflowOptions = WORKFLOW_NAMES.map((name) => ({
		value: name,
		label: name,
		icon: WorkflowIconFilled,
	}));
	const customerOptions = CUSTOMERS.map((name) => ({
		value: name,
		label: name,
		icon: (p: { className?: string }) => (
			<CustomerAvatar customerId={name} customerName={name} className={p.className} />
		),
	}));
	const metaKeyOptions = META_KEYS.map((key) => ({
		value: key as string,
		label: key as string,
		icon: MetaValueIcon,
	}));
	const metaValueOptions = (metaKey ? META_VALUES[metaKey] : []).map((v) => ({
		value: v,
		label: v,
		icon: MetaValueIcon,
	}));

	// While the entrance runs, every box between the content and its pieces
	// keeps 3D and does not clip, so each piece's lift reads (see piece.tsx).
	const entering = useEntering();
	const deep = entering && "transform-3d";

	return (
		<>
			{/* Header, each filter, rows, and footer are pieces of the hero
			    entrance (see piece.tsx); outside it they are plain elements. The
			    clear button is not: it has its own entrance, and while hidden it
			    renders nothing, so a wrapper would leave a stray gap. */}
			<Piece>
				<DemoListHeader href="/traces" title="Traces" />
			</Piece>
			<div className={cn("flex flex-col gap-4 mt-1", deep)}>
				<Toolbar className={cn(deep)}>
					<Piece>
						<FilterSelect
							value={agentFilter}
							onChange={(v) => {
								setAgentFilter(v);
								// Versions belong to one agent; a summoned prompt select
								// doesn't carry over to the next.
								setPromptFilter("");
								removeFilter("prompt");
							}}
							allLabel="Any agent"
							icon={IconGhost}
							options={agentOptions}
						/>
					</Piece>
					<Piece>
						<FilterSelect
							value={modelFilter}
							onChange={setModelFilter}
							allLabel="Any model"
							icon={IconCpu}
							options={modelOptions}
						/>
					</Piece>
					<Piece>
						<ToggleChip
							active={errorsOnly}
							onClick={() => setErrorsOnly((v) => !v)}
						>
							<IconAlertTriangle className="size-3.5" />
							Errors only
						</ToggleChip>
					</Piece>
					{showWorkflow && (
						<Piece>
							<FilterSelect
								value={workflowFilter}
								onChange={(v) => {
									setWorkflowFilter(v);
									if (!v) removeFilter("workflow");
								}}
								allLabel="Any workflow"
								icon={IconSitemap}
								options={workflowOptions}
							/>
						</Piece>
					)}
					{showCustomer && (
						<Piece>
							<FilterSelect
								value={customerFilter}
								onChange={(v) => {
									setCustomerFilter(v);
									if (!v) removeFilter("customer");
								}}
								allLabel="Any customer"
								icon={IconUser}
								options={customerOptions}
							/>
						</Piece>
					)}
					{showMeta && (
						<Piece>
							<FilterSelect
								value={metaKeyFilter}
								onChange={(v) => {
									setMetaKeyFilter(v);
									setMetaValueFilter("");
									if (!v) removeFilter("meta");
								}}
								allLabel="Any metadata"
								icon={IconTag}
								options={metaKeyOptions}
							/>
						</Piece>
					)}
					{showMeta && metaKey && (
						<Piece>
							<FilterSelect
								value={metaValueFilter}
								onChange={setMetaValueFilter}
								allLabel={`Any ${metaKey}`}
								icon={IconTag}
								options={metaValueOptions}
							/>
						</Piece>
					)}
					{showPrompt && (
						<Piece>
							<FilterSelect
								value={promptFilter}
								onChange={(v) => {
									// A version belongs to one agent: picking it without an
									// agent filter narrows to that agent as well.
									setPromptFilter(v);
									if (v && !agentFilter) setAgentFilter(promptAgentOf(v));
									if (!v) removeFilter("prompt");
								}}
								allLabel="Any prompt version"
								icon={IconFileHorizontal}
								options={promptOptions}
							/>
						</Piece>
					)}
					{canAddFilter && (
						<Piece>
							<AddFilterMenu
								showWorkflow={showWorkflow}
								showCustomer={showCustomer}
								showMeta={showMeta}
								showPrompt={showPrompt}
								onAdd={addFilter}
							/>
						</Piece>
					)}
					<ClearFiltersButton
						show={hasFilters}
						onClick={() => {
							setAgentFilter("");
							setModelFilter("");
							setWorkflowFilter("");
							setCustomerFilter("");
							setMetaKeyFilter("");
							setMetaValueFilter("");
							setPromptFilter("");
							setErrorsOnly(false);
							setAdded(new Set());
						}}
					/>
					<div className={cn("ml-auto", deep)}>
						<DemoRange />
					</div>
				</Toolbar>

				{/* Single column with no gap so the pagination footer's top border
				    sits flush against the table's last row. */}
				<div
					className={cn(
						"flex flex-col -mt-2",
						entering && ENTRANCE_TABLE
					)}
