          scrolls sideways. */}
      <motion.div
        {...rise(0.6)}
        className="mt-12 w-[150%] pl-5 sm:pl-8 md:hidden"
      >
        <DemoFrame clip>
          <img
            src="data:image/png;base64,"
            alt="The Foglamp overview dashboard"
            width={2072}
            height={1320}
            className="hidden w-full dark:block"
